import React from "react";

interface ReportRow {
  id: string;
  name: string;
  startTimeUtc: string;
  endTimeUtc: string;
  venue: string;
  attendeeCount: number;
}

interface ReportViewerProps {
  reportJson: any; // accept any shape
}

const ReportViewer: React.FC<ReportViewerProps> = ({ reportJson }) => {
  // Detect if the response is an array or has a `data` property
  const rows: ReportRow[] = Array.isArray(reportJson)
    ? reportJson
    : Array.isArray(reportJson?.data)
    ? reportJson.data
    : [];

  const generatedOn = reportJson?.reportGeneratedOn
    ? new Date(reportJson.reportGeneratedOn).toLocaleString()
    : "N/A";

  return (
    <div>
      <div>Report Generated On: {generatedOn}</div>

      {rows.length === 0 ? (
        <p>No report data available for the selected range.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Start</th>
              <th>End</th>
              <th>Venue</th>
              <th>#Attendees</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id}>
                <td>{r.name}</td>
                <td>{new Date(r.startTimeUtc).toLocaleString()}</td>
                <td>{new Date(r.endTimeUtc).toLocaleString()}</td>
                <td>{r.venue}</td>
                <td>{r.attendeeCount}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default ReportViewer;
